/*
 * This checks what is on the surface above the
 * location where an adjacent pit might be created if
 * you're zapping a wand of digging laterally while
 * down in the pit.
 */
/**
 * @param {$T.nhcoord | null} cc coord *
 * @param {$c.Ptr | null} msg char *
 * @returns {number} int
 */
function adj_pit_checks(cc, msg) {   // dig.c:1763
    let ltyp = 0;
    const foundation_msg = $C`The foundation is too hard to dig through from this angle.`;
    if (!cc) {
        return FALSE;
    }
    if (!isok(cc.x, cc.y)) {
        return FALSE;
    }
    msg.set(0, 0);
    const room = $c.relem(svl.level.locations[cc.x], cc.y);
    ltyp = room.typ, room.flags = 0;
    if (is_pool(cc.x, cc.y) || is_lava(cc.x, cc.y)) {
        /* this is handled by the caller after we return FALSE */
        return FALSE;
    } else if (closed_door(cc.x, cc.y) || room.typ === SDOOR) {
        /* We reject this here because dighole() isn't
           prepared to deal with this case */
        $c.strcpy(msg, foundation_msg);
        return FALSE;
    } else if (IS_WALL(ltyp)) {
        /* if (room->wall_info & W_NONDIGGABLE) */
        $c.strcpy(msg, foundation_msg);
        return FALSE;
    } else if (IS_TREE(ltyp)) {
        /* check trees before stone */
        /* if (room->wall_info & W_NONDIGGABLE) */
        $c.strcpy(msg, $C`The tree's roots glow then fade.`);
        return FALSE;
    } else if (ltyp === STONE || ltyp === SCORR) {
        if (room.flags & W.NONDIGGABLE) {
            $c.strcpy(msg, $C`The rock glows then fades.`);
            return FALSE;
        }
    } else if (ltyp === IRONBARS) {
        /* "set of iron bars" */
        $c.strcpy(msg, $C`The bars go much deeper than your pit.`);
        return FALSE;
    } else if (IS_SINK(ltyp)) {
        $c.strcpy(msg, $C`A tangled mass of plumbing remains below the sink.`);
        return FALSE;
    } else if (On_ladder(cc.x, cc.y)) {
        $c.strcpy(msg, $C`The ladder is unaffected.`);
        return FALSE;
    } else {
        let supporting = null;
        if (IS_FOUNTAIN(ltyp)) {
            supporting = $C`fountain`;
        } else if (IS_THRONE(ltyp)) {
            supporting = $C`throne`;
        } else if (IS_ALTAR(ltyp)) {
            supporting = $C`altar`;
        } else if (On_stairs(cc.x, cc.y)) {   /* staircase up or down. On_ladder handled above. */
            supporting = $C`stairs`;
        } else if (ltyp === DRAWBRIDGE_DOWN
            || ltyp === DBWALL) {   /* "raised drawbridge" */
            /* "lowered drawbridge" */
            supporting = $C`drawbridge`;
        }
        if (supporting) {
            $c.sprintf(msg, $C`The %s supporting structures remain intact.`, s_suffix(supporting));
            return FALSE;
        }
    }
    return TRUE;
}
