/**
 * @param {$T.obj | null} otmp struct obj *
 * @param {$c.Ptr | null} dealloced boolean *
 * @returns {Promise<$T.obj | null>} struct obj *
 */
export async function bury_an_obj(otmp, dealloced) {   // dig.c:1984
    do {
        if (debugcore($C`dig.c`, TRUE)) {
            const save_plnmsg = iflags.last_msg;
            await pline($C`bury_an_obj: %s`, await xname(otmp));
            iflags.last_msg = save_plnmsg;
        }
    } while (0);
    if (dealloced) {
        dealloced.set(0, FALSE);
    }
    if (otmp === $G.uball) {
        await unpunish();
        set_utrap(rn1(50, 20) >>> 0, TT.BURIEDBALL);
        await pline_The($C`iron ball gets buried!`);
    }
    /* after unpunish(), or might get deallocated chain */
    const otmp2 = otmp.v.v_nexthere;
    /*
     * obj_resists(,0,0) prevents Rider corpses from being buried.
     * It also prevents The Amulet and invocation tools from being
     * buried.  Since they can't be confined to bags and statues,
     * it makes sense that they can't be buried either, even though
     * the real reason there (direct accessibility when carried) is
     * completely different.
     */
    if (otmp === $G.uchain || obj_resists(otmp, 0, 0)) {
        return otmp2;
    }
    if (otmp.otyp === LEASH && otmp.corpsenm !== 0) {
        await o_unleash(otmp);
    }
    if (otmp.lamplit && otmp.otyp !== POT_OIL) {
        await end_burn(otmp, TRUE);
    }
    await obj_extract_self(otmp);
    const under_ice = is_ice(otmp.ox, otmp.oy);
    if (otmp.otyp === ROCK && !under_ice || otmp.otyp === BOULDER) {
        /* merges into burying material; boulder removal is for #wizbury */
        if (dealloced) {
            dealloced.set(0, TRUE);
        }
        await obfree(otmp, null);
        return otmp2;
    }
    /*
     * Start a rot on organic material.  Not corpses -- they
     * are already handled.
     */
    if (otmp.otyp === CORPSE) {
        /* should cancel timer if under_ice */
    } else if ((under_ice ? otmp.oclass === POTION_CLASS : is_organic(otmp))
        && !obj_resists(otmp, 5, 95)) {
        await start_timer($c.add64(under_ice ? 0 : 250, rnd(250)),
            TIMER.OBJECT, ROT_ORGANIC, obj_to_any(otmp));
        /* rusting of buried metal not yet implemented */
    }
    await add_to_buried(otmp);
    return otmp2;
}
