/* the #wizbury command - bury everything at your loc and around */
/**
 * @returns {Promise<number>} int
 */
export async function wiz_debug_cmd_bury() {   // dig.c:2288
    let otmp = null, x = 0, y = 0;
    let before = 0;
    let after = 0;
    for (x = u.ux - 1; x <= u.ux + 1; x = x + 1) {
        for (y = u.uy - 1; y <= u.uy + 1; y = y + 1) {
            if (!isok($c.i16(x), $c.i16(y))) {
                continue;
            }
            for (otmp = svl.level.objects[x][y]; otmp; otmp = otmp.v.v_nexthere) {
                before = before + 1 | 0;
            }
            await bury_objs(x, y);
            for (otmp = svl.level.objects[x][y]; otmp; otmp = otmp.v.v_nexthere) {
                after = after + 1 | 0;
            }
        }
    }
    const diff = before - after | 0;
    if (before === 0) {   /* there was nothing here */
        await pline($C`No objects here or adjacent to bury.`);
    } else if (diff === 0) {
        /* before and after will be the same if only unburiable objects are
           present (The Amulet, invocation items, Rider corpses, uchain when
           uball doesn't get buried: carried or floor beyond burial range) */
        await pline($C`No objects buried.`);
    } else {
        /* usual case; if uball got buried, uchain went away and won't be
           counted as buried */
        await pline($C`%d object%s buried.`, diff, plur(diff));
    }
    return ECMD.OK;
}
